SELECT 
  FROM LOST_TPOF L
 WHERE L.PST_SN = #{pstSn}

mapper.insert:
INSERT INTO LOST_TPOF
     ( PST_SN
     , RGN_SN
     , PET_SE_CD
     , LOST_TPOF_STTS_CD
     , PET_NM
     , COLR_NM
     , CNPL_ENC
     , WTNS_PLC_LAT
     , WTNS_PLC_LOT
     , LAST_WTNS_DT
     , EXPRY_CRTR_DT
     , WTNS_PLC_NM
     , PRVC_RLS_AGRE_YN
     , VRTY_SN
     , VRTY_DRCT_INPT_NM
     , CHRC_CN
     , REG_DT
     , MDFCN_DT )
VALUES
     ( #{pstSn}
     , #{rgnSn}
     , #{petSeCd}
     , #{lostTpofSttsCd}
     , #{petNm}
     , #{colrNm}
     , #{cnplEnc}
     , #{wtnsPlcLat}
     , #{wtnsPlcLot}
     , #{lastWtnsDt}
     , DATE_ADD(NOW(), INTERVAL 30 DAY)
     , #{wtnsPlcNm}
     , #{prvcRlsAgreYn}
     , #{vrtySn}
     , #{vrtyDrctInptNm}
     , #{chrcCn}
     , NOW()
     , NOW() )

INSERT INTO LOST_TPOF_STTS_HSTRY
     ( LOST_TPOF_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
     , REG_DT )
VALUES
     ( #{lostTpofSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
     , NOW() )

mapper.update:
UPDATE LOST_TPOF
   SET RGN_SN = #{report.rgnSn}
     , PET_SE_CD = #{report.petSeCd}
     , PET_NM = #{report.petNm}
     , COLR_NM = #{report.colrNm}
     , CNPL_ENC = #{report.cnplEnc}
     , WTNS_PLC_LAT = #{report.wtnsPlcLat}
     , WTNS_PLC_LOT = #{report.wtnsPlcLot}
     , LAST_WTNS_DT = #{report.lastWtnsDt}
     , WTNS_PLC_NM = #{report.wtnsPlcNm}
     , PRVC_RLS_AGRE_YN = #{report.prvcRlsAgreYn}
     , VRTY_SN = #{report.vrtySn}
     , VRTY_DRCT_INPT_NM = #{report.vrtyDrctInptNm}
     , CHRC_CN = #{report.chrcCn}
     , MDFCN_DT = NOW()
 WHERE LOST_TPOF_SN = #{report.lostTpofSn}
   AND LOST_TPOF_STTS_CD = #{missingCd}

UPDATE LOST_TPOF
   SET LOST_TPOF_STTS_CD = #{foundCd}
     , DSCV_SWTC_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE LOST_TPOF_SN = #{lostTpofSn}
   AND LOST_TPOF_STTS_CD = #{missingCd}
